  car.updateTransform(); world.car = world.addBody(car);

  const bw = p.brickW, bh = p.brickH, cols = p.cols, rows = p.rows;
  const wallW = cols * bw;
  let idx = 0;
  for (let k = 0; k < p.layers; k++) {
    const shade = Math.pow(0.78, k);
    for (let r = 0; r < rows; r++) {
      const staggered = (r + k) % 2 === 1;
      const y = r * bh + bh / 2;
      const place = (cx, w) => {
        const b = new Body(w / 2, bh / 2, p.brickMass * (w / bw));
        b.x = cx; b.y = y; b.x0 = cx; b.y0 = y; b.layer = k; b.kind = 'brick';
        b.friction = p.brickFriction; b.restitution = p.brickRestitution;
        const t = brickHash(idx++);
        const rr = 168 + t * 40, gg = 72 + t * 26, bb = 52 + t * 18;
        b.faceCol = rgb(rr, gg, bb, shade); b.topCol = rgb(rr, gg, bb, shade * 0.86); b.sideCol = rgb(rr, gg, bb, shade * 0.6);
        b.updateTransform();
        world.bricks.push(world.addBody(b));
      };
      if (!staggered) { for (let c = 0; c < cols; c++) place(c * bw + bw / 2, bw); }
      else {
        place(bw / 4, bw / 2);
        for (let c = 0; c < cols - 1; c++) place(bw / 2 + c * bw + bw / 2, bw);
        place(wallW - bw / 4, bw / 2);
      }
    }
  }
  // Pre-stress the wall: let gravity load every contact (warm-start impulses, micro-penetration)
  // with the car parked far away, then freeze the wall as one sleeping island.
  car.asleep = true;
  for (const b of world.bricks) b.canSleep = false;
  for (let i = 0; i < PRESETTLE_STEPS; i++) world.step(STEP_H);
  for (const b of world.bricks) { b.canSleep = true; b.x0 = b.x; b.y0 = b.y; }
  world.forceSleepAll();
  world.activeArbs.length = 0;
  car.asleep = false; car.sleepTime = 0;
  return { world, car, ground, launchAccel, runup, startDist, wallW, wallH: rows * bh, params: { ...p } };
}

