function recordSkid() {
  const car = scene.car, r = Math.min(0.34, car.hh * 0.5);
  const ly = -car.hh + r;
  for (let i = 0; i < 2; i++) {
    const lx = (i === 0 ? -1 : 1) * car.hw * 0.6;
    const wx = car.x + car.cos * lx - car.sin * ly;
