function spawnDust(events) {
  for (const e of events) {
    if (particles.length > 700) break;
    const count = e.car ? 3 : Math.min(2, 1 + Math.floor(e.dv / 4));
    for (let i = 0; i < count; i++) {
      const spread = (rng() - 0.5) * 1.6;
      const speed = Math.min(6, 0.6 + e.dv * 0.25) * (0.4 + rng() * 0.8);
      const tx = e.ny, ty = -e.nx;
      particles.push({
        x: e.x, y: e.y,
        vx: (e.nx * 0.4 + tx * spread) * speed * (rng() < 0.5 ? -1 : 1), vy: Math.abs(e.ny) * speed * 0.5 + rng() * speed * 0.6,
        life: 0, maxLife: 0.5 + rng() * 0.8, r: 0.05 + rng() * 0.1, warm: e.car ? 0.4 + rng() * 0.6 : rng() * 0.5,
      });
    }
  }
}

function updateParticles(dt) {
  const g = scene.params.gravity * 0.25;
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.life += dt;
    if (p.life > p.maxLife) { particles[i] = particles[particles.length - 1]; particles.pop(); continue; }
    p.vx *= Math.exp(-2.2 * dt); p.vy = p.vy * Math.exp(-2.2 * dt) - g * dt;
    p.x += p.vx * dt; p.y += p.vy * dt;
    if (p.y < 0.02) { p.y = 0.02; p.vy = Math.abs(p.vy) * 0.2; }
    p.r += dt * 0.35;
  }
}

