function updateParticles(dt) {
  const g = scene.params.gravity * 0.25;
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.life += dt;
    if (p.life > p.maxLife) { particles[i] = particles[particles.length - 1]; particles.pop(); continue; }
    p.vx *= Math.exp(-2.2 * dt); p.vy = p.vy * Math.exp(-2.2 * dt) - g * dt;
    p.x += p.vx * dt; p.y += p.vy * dt;
    if (p.y < 0.02) { p.y = 0.02; p.vy = Math.abs(p.vy) * 0.2; }
    p.r += dt * 0.35;
  }
}

function updateCamera(dt) {
  const usableM = usableWidthPx() / viewScale;
  const car = scene.car;
  let target = camera.restX;
  if (state !== 'ready') {
    // keep the rightmost action (car nose, wall, nearby flying debris) inside the usable view
    let right = Math.max(car.x + car.hw, scene.wallW);
    const cap = car.x + car.hw + 6;
    for (const b of scene.world.bricks) if (!b.asleep && b.maxX > right && b.maxX < cap) right = b.maxX;
    target = Math.max(camera.restX, right + 0.8 - usableM);
  }
  camera.target = target;

