class Arbiter {
  constructor(a, b) {
    this.a = a; this.b = b;
    this.contacts = [new Contact(), new Contact()];
    this.spare = [new Contact(), new Contact()];
    this.n = 0; this.stamp = 0;
    this.friction = 0; this.restitution = 0;
    this.im1 = 0; this.iI1 = 0; this.im2 = 0; this.iI2 = 0;
  }
  update(newC, n) {
    const spare = this.spare, old = this.contacts;
    for (let i = 0; i < n; i++) {
      const nc = newC[i], s = spare[i];
      s.px = nc.px; s.py = nc.py; s.nx = nc.nx; s.ny = nc.ny; s.separation = nc.separation; s.feature = nc.feature;
      s.Pn = 0; s.Pt = 0; s.Pnb = 0;
      for (let j = 0; j < this.n; j++) {
        if (old[j].feature === nc.feature) { s.Pn = old[j].Pn; s.Pt = old[j].Pt; break; }
      }
    }
    this.spare = old; this.contacts = spare; this.n = n;
    this.friction = Math.sqrt(this.a.friction * this.b.friction);
    this.restitution = Math.max(this.a.restitution, this.b.restitution);
  }
  preStep(invH) {
    const a = this.a, b = this.b;
    const im1 = a.inactive ? 0 : a.invMass, iI1 = a.inactive ? 0 : a.invI;
    const im2 = b.inactive ? 0 : b.invMass, iI2 = b.inactive ? 0 : b.invI;
    this.im1 = im1; this.iI1 = iI1; this.im2 = im2; this.iI2 = iI2;
    for (let i = 0; i < this.n; i++) {
      const c = this.contacts[i];
      const r1x = c.px - a.x, r1y = c.py - a.y, r2x = c.px - b.x, r2y = c.py - b.y;
      c.r1x = r1x; c.r1y = r1y; c.r2x = r2x; c.r2y = r2y;
      const nx = c.nx, ny = c.ny, tx = ny, ty = -nx;
      const r1sq = r1x * r1x + r1y * r1y, r2sq = r2x * r2x + r2y * r2y;
      const rn1 = r1x * nx + r1y * ny, rn2 = r2x * nx + r2y * ny;
      const kN = im1 + im2 + iI1 * (r1sq - rn1 * rn1) + iI2 * (r2sq - rn2 * rn2);
      c.massNormal = kN > 0 ? 1 / kN : 0;
      const rt1 = r1x * tx + r1y * ty, rt2 = r2x * tx + r2y * ty;
      const kT = im1 + im2 + iI1 * (r1sq - rt1 * rt1) + iI2 * (r2sq - rt2 * rt2);
      c.massTangent = kT > 0 ? 1 / kT : 0;
      if (c.separation > 0) { c.bias = 0; c.specBias = -c.separation * invH; }   // may approach, but only close the gap
      else { c.bias = -BIAS_FACTOR * invH * Math.min(0, c.separation + ALLOWED_PENETRATION); c.specBias = 0; }
      const dvx = b.vx - b.w * r2y - a.vx + a.w * r1y;
      const dvy = b.vy + b.w * r2x - a.vy - a.w * r1x;
      const vn = dvx * nx + dvy * ny;
      // approach speed at the start of the step; restitution is applied in a separate pass after
      // the main iterations so bounce targets never fight resting-contact convergence
      c.velBias = vn < -RESTITUTION_VEL ? -this.restitution * vn : 0;
      // warm start
      const Px = c.Pn * nx + c.Pt * tx, Py = c.Pn * ny + c.Pt * ty;
      a.vx -= im1 * Px; a.vy -= im1 * Py; a.w -= iI1 * (r1x * Py - r1y * Px);
      b.vx += im2 * Px; b.vy += im2 * Py; b.w += iI2 * (r2x * Py - r2y * Px);
    }
  }
  applyRestitution() {
    const a = this.a, b = this.b, im1 = this.im1, iI1 = this.iI1, im2 = this.im2, iI2 = this.iI2;
    for (let i = 0; i < this.n; i++) {
      const c = this.contacts[i];
      if (c.velBias === 0 || c.Pn === 0) continue;
      const r1x = c.r1x, r1y = c.r1y, r2x = c.r2x, r2y = c.r2y, nx = c.nx, ny = c.ny;
      const dvx = b.vx - b.w * r2y - a.vx + a.w * r1y;
      const dvy = b.vy + b.w * r2x - a.vy - a.w * r1x;
      const vn = dvx * nx + dvy * ny;
      let dPn = c.massNormal * (-vn + c.velBias);
      const Pn0 = c.Pn;
      c.Pn = Math.max(Pn0 + dPn, 0);
      dPn = c.Pn - Pn0;
      const Px = dPn * nx, Py = dPn * ny;
      a.vx -= im1 * Px; a.vy -= im1 * Py; a.w -= iI1 * (r1x * Py - r1y * Px);
      b.vx += im2 * Px; b.vy += im2 * Py; b.w += iI2 * (r2x * Py - r2y * Px);
    }
  }
  applyImpulse() {
    const a = this.a, b = this.b, im1 = this.im1, iI1 = this.iI1, im2 = this.im2, iI2 = this.iI2, mu = this.friction;
    for (let i = 0; i < this.n; i++) {
      const c = this.contacts[i];
      const r1x = c.r1x, r1y = c.r1y, r2x = c.r2x, r2y = c.r2y, nx = c.nx, ny = c.ny;
      let dvx = b.vx - b.w * r2y - a.vx + a.w * r1y;
      let dvy = b.vy + b.w * r2x - a.vy - a.w * r1x;
      const vn = dvx * nx + dvy * ny;
      let dPn = c.massNormal * (-vn + c.specBias);
      const Pn0 = c.Pn;
      c.Pn = Math.max(Pn0 + dPn, 0);
      dPn = c.Pn - Pn0;
      let Px = dPn * nx, Py = dPn * ny;
      a.vx -= im1 * Px; a.vy -= im1 * Py; a.w -= iI1 * (r1x * Py - r1y * Px);
      b.vx += im2 * Px; b.vy += im2 * Py; b.w += iI2 * (r2x * Py - r2y * Px);

      // position correction through pseudo velocities so it never injects kinetic energy
      if (c.bias > 0 || c.Pnb > 0) {
        const bvn = (b.bvx - b.bw * r2y - a.bvx + a.bw * r1y) * nx + (b.bvy + b.bw * r2x - a.bvy - a.bw * r1x) * ny;
        let dPnb = c.massNormal * (-bvn + c.bias);
        const Pnb0 = c.Pnb;
        c.Pnb = Math.max(Pnb0 + dPnb, 0);
        dPnb = c.Pnb - Pnb0;
        const Bx = dPnb * nx, By = dPnb * ny;
        a.bvx -= im1 * Bx; a.bvy -= im1 * By; a.bw -= iI1 * (r1x * By - r1y * Bx);
        b.bvx += im2 * Bx; b.bvy += im2 * By; b.bw += iI2 * (r2x * By - r2y * Bx);
      }

      dvx = b.vx - b.w * r2y - a.vx + a.w * r1y;
      dvy = b.vy + b.w * r2x - a.vy - a.w * r1x;
      const tx = ny, ty = -nx;
      const vt = dvx * tx + dvy * ty;
      let dPt = c.massTangent * (-vt);
      const maxPt = mu * c.Pn;
      const Pt0 = c.Pt;
      c.Pt = Math.max(-maxPt, Math.min(maxPt, Pt0 + dPt));
      dPt = c.Pt - Pt0;
      Px = dPt * tx; Py = dPt * ty;
      a.vx -= im1 * Px; a.vy -= im1 * Py; a.w -= iI1 * (r1x * Py - r1y * Px);
      b.vx += im2 * Px; b.vy += im2 * Py; b.w += iI2 * (r2x * Py - r2y * Px);
    }
  }
}

