+    } catch (e) {}
+  }
+
+  updateEngine(speed, maxSpeed) {
+    if (!this.engineNode || !this.ctx) return;
+    try {
+      const pitch = 55 + (speed / maxSpeed) * 160;
+      this.engineNode.frequency.setTargetAtTime(pitch, this.ctx.currentTime, 0.05);
+    } catch (e) {}
+  }
+
+  stopEngine() {
+    if (this.engineGain && this.ctx) {
+      try {
+        this.engineGain.gain.setTargetAtTime(0.001, this.ctx.currentTime, 0.08);
+        setTimeout(() => {
+          if (this.engineNode) {
+            try { this.engineNode.stop(); } catch (e) {}
