+/* =====================================================================
+   SCENE BUILDER
+   ===================================================================== */
+function buildScene(p) {
+  nextBodyId = 1;
+  const cellSize = Math.max(0.3, Math.max(p.brickW, p.brickH) * 1.3);
+  const brickCount = (p.rows * p.cols + p.rows) * p.layers + 8;
+  const world = new World(p.gravity, p.layers, cellSize, brickCount);
+
+  // Ground plane body (static)
+  const ground = new Body(350, 2.0, Infinity);
+  ground.x = 25;
+  ground.y = -2.0;
+  ground.kind = 'ground';
+  ground.friction = p.groundFriction;
+  ground.restitution = 0.02;
+  ground.updateTransform();
+  world.ground = world.addBody(ground);
+
+  // Runway geometry calculation
+  const maxLaunchAccel = 16.0; // m/s² realistic sports sedan acceleration
+  const runupDist = Math.max(12.0, (p.carSpeed * p.carSpeed) / (2 * maxLaunchAccel));
+  const coastDist = 3.5;
+  const launchDist = runupDist + coastDist;
+  const launchAccel = (p.carSpeed * p.carSpeed) / (2 * runupDist);
+
+  // Car Body
+  const car = new Body(p.carW / 2, p.carH / 2, p.carMass);
+  car.kind = 'car';
+  car.x = -launchDist - p.carW / 2;
+  car.y = p.carH / 2;
+  car.friction = 0.05; // low rolling resistance before impact
+  car.restitution = 0.05;
+  car.canSleep = false;
+  car.updateTransform();
+  world.car = world.addBody(car);
+
+  // Bricks construction
+  const bw = p.brickW, bh = p.brickH, cols = p.cols, rows = p.rows;
+  const wallW = cols * bw;
+  let brickIdx = 0;
+
+  for (let l = 0; l < p.layers; l++) {
+    const shade = Math.pow(0.76, l);
+    for (let r = 0; r < rows; r++) {
+      const isStaggered = (r + l) % 2 === 1;
+      const y = r * bh + bh / 2;
+
+      const placeBrick = (cx, w) => {
+        const b = new Body(w / 2, bh / 2, p.brickMass * (w / bw));
+        b.x = cx; b.y = y;
+        b.x0 = cx; b.y0 = y;
+        b.layer = l;
+        b.kind = 'brick';
+        b.friction = p.brickFriction;
+        b.restitution = p.brickRestitution;
+
+        // Deterministic brick tint
+        const t = (Math.sin(brickIdx * 19.3 + l * 7.1 + r * 13.7) + 1) * 0.5;
+        brickIdx++;
+        const red = Math.round((180 + t * 45) * shade);
+        const green = Math.round((70 + t * 24) * shade);
+        const blue = Math.round((48 + t * 18) * shade);
+        b.faceCol = `rgb(${red},${green},${blue})`;
+        b.topCol = `rgb(${Math.round(red * 1.15)},${Math.round(green * 1.15)},${Math.round(blue * 1.15)})`;
+        b.sideCol = `rgb(${Math.round(red * 0.65)},${Math.round(green * 0.65)},${Math.round(blue * 0.65)})`;
+        b.updateTransform();
+        world.bricks.push(world.addBody(b));
+      };
+
+      if (!isStaggered) {
+        for (let c = 0; c < cols; c++) placeBrick(c * bw + bw / 2, bw);
+      } else {
+        placeBrick(bw / 4, bw / 2);
+        for (let c = 0; c < cols - 1; c++) placeBrick(bw / 2 + c * bw + bw / 2, bw);
+        placeBrick(wallW - bw / 4, bw / 2);
+      }
+    }
+  }
+
+  // Pre-stress settling: allow wall to settle microscopically under gravity
+  car.asleep = true;
+  for (const b of world.bricks) b.canSleep = false;
+  for (let i = 0; i < 18; i++) world.step(PHYSICS_DT);
+  for (const b of world.bricks) {
+    b.canSleep = true;
+    b.x0 = b.x;
+    b.y0 = b.y;
+  }
+  world.forceSleepAll();
+  world.activeArbs.length = 0;
+  car.asleep = false;
+  car.sleepTime = 0;
+
+  return {
+    world,
+    car,
+    ground,
+    launchAccel,
+    runupDist,
+    launchDist,
+    wallW,
+    wallH: rows * bh,
+    params: { ...p }
+  };
+}
