+/* =====================================================================
+   APPLICATION STATE & PARTICLES
+   ===================================================================== */
+const canvas = document.getElementById('viewport');
+const ctx = canvas.getContext('2d');
+let W = 0, H = 0, dpr = 1;
+
+let scene = null;
+let state = 'ready'; // ready | accelerating | impact | settling | settled
+let simTime = 0, accumulator = 0;
+let timeScale = 1.0;
+let driving = false, impacted = false, impactTime = 0, impactSpeed = 0, peakDecelG = 0;
+let prevCarVx = 0, initialCarKE = 0;
+let settledAt = 0;
+let carCrush = 0;
+
+const camera = { x: 0, target: 0, restX: 0, shake: 0, shakeX: 0, shakeY: 0 };
+const particles = [];
+const skidMarks = [[], []]; // rear and front wheel skid trajectories
