+/* =====================================================================
+   PARTICLE SYSTEM & VISUAL EFFECTS
+   ===================================================================== */
+function spawnImpactVfx(events) {
+  for (const e of events) {
+    if (particles.length > 400) break;
+    const count = e.isCar ? 4 : Math.min(3, 1 + Math.floor(e.dv / 3));
+    for (let i = 0; i < count; i++) {
+      const spread = (mulberry32() - 0.5) * 2.0;
+      const speed = Math.min(7.0, 0.8 + e.dv * 0.35) * (0.5 + mulberry32() * 0.8);
+      particles.push({
+        x: e.x,
+        y: e.y,
+        vx: (e.nx * 0.5 + e.ny * spread) * speed,
+        vy: Math.abs(e.ny) * speed * 0.6 + mulberry32() * speed * 0.5,
+        life: 0,
+        maxLife: 0.4 + mulberry32() * 0.7,
+        r: 0.04 + mulberry32() * 0.08,
+        warm: e.isCar ? 0.7 + mulberry32() * 0.3 : mulberry32() * 0.4
+      });
+    }
+  }
+}
+
+function updateParticles(dt) {
+  const g = scene.params.gravity * 0.25;
+  for (let i = particles.length - 1; i >= 0; i--) {
+    const p = particles[i];
+    p.life += dt;
+    if (p.life > p.maxLife) {
+      particles[i] = particles[particles.length - 1];
+      particles.pop();
+      continue;
+    }
+    p.vx *= Math.exp(-2.5 * dt);
+    p.vy = p.vy * Math.exp(-2.5 * dt) - g * dt;
+    p.x += p.vx * dt;
+    p.y += p.vy * dt;
+    if (p.y < 0.02) { p.y = 0.02; p.vy = Math.abs(p.vy) * 0.2; }
+    p.r += dt * 0.28;
+  }
+}
+
+function recordSkidMarks() {
+  const car = scene.car, r = Math.min(0.35, car.hh * 0.48);
+  const ly = -car.hh + r;
+  for (let i = 0; i < 2; i++) {
+    const lx = (i === 0 ? -1 : 1) * car.hw * 0.62;
+    const wx = car.x + car.cos * lx - car.sin * ly;
+    const wy = car.y + car.sin * lx + car.cos * ly;
+    if (wy < r + 0.06) {
+      const arr = skidMarks[i];
+      if (arr.length === 0 || Math.abs(arr[arr.length - 1] - wx) > 0.03) arr.push(wx);
+    }
+  }
+}
+
+/* =====================================================================
+   CAMERA & SCALING
+   ===================================================================== */
+let viewScale = DEFAULTS.scale;
+
+function computeViewScale() {
+  const panel = document.getElementById('settingsPanel');
+  const panelReserve = (W > 920 && !panel.classList.contains('collapsed')) ? 360 : 60;
+  const usableWidth = Math.max(340, W - panelReserve);
+  const restSpan = (scene.wallW + 4.5) - (scene.car.x - scene.car.hw - 1.5);
+  const fitW = usableWidth / Math.max(16, restSpan);
+  const groundY = Math.min(Math.round(H * 0.72), H - 140);
+  const fitH = (groundY - 100) / Math.max(scene.wallH + 2.0, 3.5);
+  viewScale = Math.min(scene.params.scale, Math.max(32, Math.min(fitW, fitH)));
+}
+
+function restCameraX() {
+  return scene.car.x - scene.car.hw - 1.2;
+}
+
+function updateCamera(dt) {
+  const panel = document.getElementById('settingsPanel');
+  const panelReserve = (W > 920 && !panel.classList.contains('collapsed')) ? 360 : 40;
+  const usableM = Math.max(340, W - panelReserve) / viewScale;
+  let target = camera.restX;
+
+  if (state !== 'ready') {
+    let focusRight = Math.max(scene.car.x + scene.car.hw, scene.wallW);
+    const cap = scene.car.x + scene.car.hw + 6.0;
+    for (const b of scene.world.bricks) {
+      if (!b.asleep && b.maxX > focusRight && b.maxX < cap) focusRight = b.maxX;
+    }
+    target = Math.max(camera.restX, focusRight + 1.2 - usableM);
+  }
+  camera.target = target;
+  camera.x += (camera.target - camera.x) * Math.min(1.0, dt * 5.0);
+
+  // Camera trauma shake decay
+  if (camera.shake > 0) {
+    camera.shakeX = (mulberry32() - 0.5) * camera.shake * 1.8;
+    camera.shakeY = (mulberry32() - 0.5) * camera.shake * 1.4;
+    camera.shake = Math.max(0, camera.shake - dt * 28);
+  } else {
+    camera.shakeX = 0;
+    camera.shakeY = 0;
+  }
+}
+
+function toScreenX(wx) {
+  const panel = document.getElementById('settingsPanel');
+  const panelReserve = (W > 920 && !panel.classList.contains('collapsed')) ? 350 : 25;
+  return Math.round(panelReserve + (wx - camera.x) * viewScale + camera.shakeX);
+}
+
+function toScreenY(wy) {
+  const groundY = Math.min(Math.round(H * 0.72), H - 140);
+  return Math.round(groundY - wy * viewScale + camera.shakeY);
+}
+
+/* =====================================================================
+   SCENE RESET & STEP
+   ===================================================================== */
+function resetScene() {
+  scene = buildScene(settings);
+  state = 'ready';
+  simTime = 0;
+  accumulator = 0;
+  driving = false;
+  impacted = false;
+  impactTime = 0;
+  impactSpeed = 0;
+  peakDecelG = 0;
+  prevCarVx = 0;
+  settledAt = 0;
+  carCrush = 0;
+  initialCarKE = 0.5 * settings.carMass * settings.carSpeed * settings.carSpeed;
+
+  particles.length = 0;
+  skidMarks[0].length = 0;
+  skidMarks[1].length = 0;
+  resetRng(1337);
+
+  computeViewScale();
+  camera.restX = restCameraX();
+  camera.x = camera.target = camera.restX;
+  camera.shake = 0;
+
+  audio.stopEngine();
+  updateHUD();
+}
+
+function runPhysicsStep(h) {
+  const { world, car } = scene;
+
+  // Car engine acceleration along runway
+  if (driving) {
+    car.fx = car.mass * scene.launchAccel;
+    audio.updateEngine(car.vx, scene.params.carSpeed);
+    if (car.vx >= scene.params.carSpeed) {
+      car.vx = scene.params.carSpeed;
+      driving = false;
+    }
+  }
+
+  // Realistic suspension stabilization
+  car.torque -= car.a * 75000 + car.w * 12000;
+
+  prevCarVx = car.vx;
+  world.step(h);
+
+  // Impact detection
+  if (!impacted && world.carTouch) {
+    impacted = true;
+    impactTime = simTime;
+    impactSpeed = Math.abs(prevCarVx);
+    driving = false;
+    car.friction = scene.params.groundFriction;
+    car.canSleep = true;
+    camera.shake = Math.max(camera.shake, Math.min(26, 6 + impactSpeed * 0.65));
+    audio.playImpact(Math.min(2.0, impactSpeed / 18));
+    audio.stopEngine();
+  }
+
+  // Post-impact kinematics
+  if (impacted) {
+    const decel = (prevCarVx - car.vx) / h / 9.81;
+    if (decel > peakDecelG) peakDecelG = decel;
+    if (decel > 2.5) {
+      camera.shake = Math.max(camera.shake, Math.min(24, decel * 0.45));
+    }
+    if (Math.abs(car.vx) > 0.4 && car.minY < 0.08) {
+      recordSkidMarks();
+      if (Math.random() < 0.08) audio.playSkid();
+    }
+    // Calculate plastic crumple zone deformation
+    const speedLoss = Math.max(0, impactSpeed - Math.abs(car.vx));
+    carCrush = Math.min(0.48, (speedLoss / Math.max(10, scene.params.carSpeed)) * 0.40 + Math.min(0.08, peakDecelG / 800));
+  }
+
+  simTime += h;
+  spawnImpactVfx(world.contactEvents);
+
+  // Settle condition
+  if (impacted && simTime - impactTime > 0.4) {
+    let allAsleep = car.asleep || Math.abs(car.vx) < 0.08;
+    if (allAsleep) {
+      for (const b of world.bricks) {
+        if (!b.asleep && (b.vx * b.vx + b.vy * b.vy > 0.02 || Math.abs(b.w) > 0.08)) {
+          allAsleep = false;
+          break;
+        }
+      }
+    }
+    if (allAsleep) {
+      state = 'settled';
+      settledAt = simTime;
+    }
+  }
+
+  if (simTime > 90) {
+    state = 'settled';
+    settledAt = simTime;
+  }
+}
+
+/* =====================================================================
+   CANVAS RENDERING PIPELINE
+   ===================================================================== */
+function drawScene() {
+  ctx.clearRect(0, 0, W, H);
+  const groundY = Math.min(Math.round(H * 0.72), H - 140);
+
+  // 1. Proving Ground Indoor Arena Background
+  const grad = ctx.createLinearGradient(0, 0, 0, H);
+  grad.addColorStop(0, '#090d16');
+  grad.addColorStop(0.65, '#121826');
+  grad.addColorStop(1, '#080c14');
+  ctx.fillStyle = grad;
+  ctx.fillRect(0, 0, W, H);
