+  // Distance Metric Grid
+  ctx.save();
+  ctx.strokeStyle = 'rgba(255, 255, 255, 0.035)';
+  ctx.lineWidth = 1;
+  const startM = Math.floor(camera.x - 5);
+  const endM = Math.ceil(camera.x + W / viewScale + 5);
