+  for (let m = startM; m <= endM; m++) {
+    const sx = toScreenX(m);
+    ctx.beginPath();
+    ctx.moveTo(sx, 0);
+    ctx.lineTo(sx, groundY);
+    ctx.stroke();
+
+    if (m % 2 === 0) {
+      ctx.fillStyle = (m === 0) ? 'rgba(6, 182, 212, 0.5)' : 'rgba(255, 255, 255, 0.18)';
+      ctx.font = '10px "JetBrains Mono", monospace';
+      const label = (m === 0) ? '0m IMPACT' : `${m > 0 ? '+' : ''}${m}m`;
+      ctx.fillText(label, sx + 4, groundY - 14);
+    }
+  }
+  ctx.restore();
+
+  // 2. Concrete Wall Foundation Footer at x = 0
+  const fStartX = toScreenX(0);
+  const fWidth = scene.wallW * viewScale;
+  ctx.fillStyle = '#1e2638';
+  ctx.fillRect(fStartX - 6, groundY, fWidth + 12, 22);
+  ctx.fillStyle = '#0f1420';
+  ctx.fillRect(fStartX - 6, groundY + 22, fWidth + 12, H - (groundY + 22));
+  ctx.fillStyle = '#38bdf8';
+  ctx.fillRect(fStartX - 6, groundY, fWidth + 12, 2);
+
+  // 3. Asphalt Test Track & Hazard Curbing
+  ctx.fillStyle = '#111622';
+  ctx.fillRect(0, groundY, W, H - groundY);
+  ctx.strokeStyle = '#252f44';
+  ctx.lineWidth = 2;
+  ctx.beginPath();
+  ctx.moveTo(0, groundY);
+  ctx.lineTo(W, groundY);
+  ctx.stroke();
+
+  // Hazard striped safety curbing
