+  for (let x = 0; x < W; x += stripeW * 2) {
+    ctx.fillStyle = '#f59e0b';
+    ctx.fillRect(x, groundY, stripeW, curbH);
+    ctx.fillStyle = '#1e293b';
+    ctx.fillRect(x + stripeW, groundY, stripeW, curbH);
+  }
