+  // Skid Marks
+  ctx.save();
+  ctx.fillStyle = 'rgba(15, 18, 26, 0.65)';
+  for (let s = 0; s < 2; s++) {
+    const pts = skidMarks[s];
+    for (let i = 0; i < pts.length; i++) {
+      const sx = toScreenX(pts[i]);
+      ctx.fillRect(sx - 3, groundY + 1, 6, 4);
+    }
+  }
+  ctx.restore();
