+}
+
+function drawBricks(groundY) {
+  const layers = scene.params.layers;
+  const depthOffset = 0.11 * viewScale;
+  const ex = depthOffset * 0.72, ey = -depthOffset * 0.48;
+
+  for (let l = layers - 1; l >= 0; l--) {
+    const ox = l * ex, oy = l * ey;
