+      ctx.moveTo(bw / 2, -bh / 2);
+      ctx.lineTo(bw / 2, bh / 2);
+      ctx.lineTo(-bw / 2, bh / 2);
+      ctx.stroke();
+
+      ctx.restore();
+    }
+  }
+}
+
+function drawHeadlightBeam(groundY) {
+  const car = scene.car;
+  const noseX = toScreenX(car.x + car.hw * (1 - carCrush * 0.5));
+  const lightY = toScreenY(car.y - car.hh * 0.15);
