+  ctx.save();
+  const grad = ctx.createRadialGradient(noseX, lightY, 10, noseX + 320, lightY, 400);
+  grad.addColorStop(0, 'rgba(255, 245, 200, 0.28)');
+  grad.addColorStop(0.4, 'rgba(255, 245, 200, 0.12)');
