+
+function drawCar(groundY) {
+  const car = scene.car;
+  const hw = car.hw, hh = car.hh;
+  const cx = toScreenX(car.x);
+  const cy = toScreenY(car.y);
+
+  // Drop shadow
+  ctx.fillStyle = 'rgba(0, 0, 0, 0.42)';
