+  ctx.beginPath();
+  ctx.moveTo(-hw, -hh + r * 0.75);
+  ctx.lineTo(-hw, yBelt - 0.08);
+  ctx.lineTo(-hw + 0.25, yBelt);
+  ctx.lineTo(-hw * 0.48, yBelt);
+  ctx.lineTo(-hw * 0.22, hh);
+  ctx.lineTo(fx(hw * 0.15), hh);
+  ctx.lineTo(fx(hw * 0.52), yBelt);
+  ctx.lineTo(fx(hw - 0.22), yBelt - 0.05);
+  ctx.lineTo(fx(hw), yBelt - 0.35);
+  ctx.lineTo(fx(hw), -hh + r * 0.75);
