+  const bodyGrad = ctx.createLinearGradient(0, -hh, 0, hh);
+  bodyGrad.addColorStop(0, '#cbd5e1');
+  bodyGrad.addColorStop(0.5, '#f8fafc');
+  bodyGrad.addColorStop(1, '#ffffff');
