+  ctx.beginPath();
+  ctx.moveTo(-hw * 0.44, yBelt + 0.03);
+  ctx.lineTo(-hw * 0.20, hh - 0.07);
+  ctx.lineTo(fx(hw * 0.13), hh - 0.07);
+  ctx.lineTo(fx(hw * 0.46), yBelt + 0.03);
+  ctx.closePath();
+  ctx.fill();
+
+  // B-pillar
+  ctx.strokeStyle = '#e2e8f0';
+  ctx.lineWidth = 0.035;
+  ctx.beginPath();
+  ctx.moveTo(-hw * 0.05, yBelt + 0.03);
+  ctx.lineTo(-hw * 0.05, hh - 0.07);
+  ctx.stroke();
+
+  // 3. High-Visibility Safety Livery Stripe
+  ctx.fillStyle = '#f97316';
+  ctx.fillRect(-hw + 0.06, yBelt - 0.35, fx(hw) + hw - 0.16, 0.09);
+
+  // 4. Euro NCAP / IIHS Crash Calibration Target (Door)
+  const tx = -hw * 0.06, ty = -hh + r * 0.75 + (yBelt - (-hh + r * 0.75)) * 0.44;
+  const tr = Math.min(0.18, hh * 0.22);
+  for (let q = 0; q < 4; q++) {
+    ctx.fillStyle = q % 2 ? '#0f172a' : '#facc15';
+    ctx.beginPath();
+    ctx.moveTo(tx, ty);
+    ctx.arc(tx, ty, tr, (q * Math.PI) / 2, ((q + 1) * Math.PI) / 2);
+    ctx.closePath();
+    ctx.fill();
+  }
+
+  // 5. Lights
+  ctx.fillStyle = '#fef08a'; // Headlight
+  ctx.fillRect(fx(hw) - 0.16, yBelt - 0.32, 0.15, 0.12);
+  ctx.fillStyle = '#ef4444'; // Taillight
+  ctx.fillRect(-hw + 0.02, yBelt - 0.32, 0.12, 0.12);
+
+  // 6. Wheels & Rims (Spinning sync with car travel)
+  for (const wxl of [-hw * 0.62, hw * 0.62]) {
+    const wx = wxl > 0 ? fx(wxl) : wxl, wy = -hh + r;
+    // Rubber tire
+    ctx.fillStyle = '#0f172a';
+    ctx.beginPath();
+    ctx.arc(wx, wy, r, 0, Math.PI * 2);
+    ctx.fill();
+    // Alloy rim
+    ctx.fillStyle = '#94a3b8';
+    ctx.beginPath();
+    ctx.arc(wx, wy, r * 0.62, 0, Math.PI * 2);
+    ctx.fill();
+    // 5-Spoke wheel rotation
+    ctx.strokeStyle = '#475569';
+    ctx.lineWidth = 0.035;
+    const spin = car.x / r;
+    for (let s = 0; s < 5; s++) {
+      const ang = spin + (s * Math.PI * 2) / 5;
+      ctx.beginPath();
+      ctx.moveTo(wx, wy);
+      ctx.lineTo(wx + Math.cos(ang) * r * 0.52, wy + Math.sin(ang) * r * 0.52);
+      ctx.stroke();
+    }
+    // Hub cap
+    ctx.fillStyle = '#1e293b';
+    ctx.beginPath();
+    ctx.arc(wx, wy, r * 0.16, 0, Math.PI * 2);
+    ctx.fill();
+  }
+
+  ctx.restore();
+}
+
+function drawParticles() {
+  for (const p of particles) {
+    const t = p.life / p.maxLife, alpha = (1 - t) * 0.55;
+    const sx = toScreenX(p.x), sy = toScreenY(p.y);
+    const rpx = p.r * viewScale;
+
+    ctx.save();
+    ctx.fillStyle = p.warm > 0.5
+      ? `rgba(251, 146, 60, ${alpha.toFixed(3)})`
+      : `rgba(180, 160, 140, ${alpha.toFixed(3)})`;
+    ctx.beginPath();
+    ctx.arc(sx, sy, rpx, 0, Math.PI * 2);
+    ctx.fill();
+    ctx.restore();
+  }
+}
+
+/* =====================================================================
+   MAIN ANIMATION LOOP
+   ===================================================================== */
+let lastFrameTime = performance.now();
+
+function animate(now) {
+  const rawDt = Math.min(0.1, (now - lastFrameTime) / 1000);
+  lastFrameTime = now;
+
+  const dt = rawDt * timeScale;
+  accumulator += dt;
+
+  let steps = 0;
+  while (accumulator >= PHYSICS_DT && steps < 8) {
+    if (state === 'accelerating' || state === 'impact' || state === 'settling') {
+      runPhysicsStep(PHYSICS_DT);
+    }
+    accumulator -= PHYSICS_DT;
+    steps++;
+  }
+
+  updateParticles(dt);
+  updateCamera(rawDt);
+  drawScene();
+  updateHUD();
+
+  requestAnimationFrame(animate);
+}
+
+/* =====================================================================
+   USER INTERACTION & CONTROLS
+   ===================================================================== */
+function launchTest() {
+  audio.init();
+  resetScene();
+  state = 'accelerating';
+  driving = true;
+  audio.startEngine(0);
+}
+
+function resetExperiment() {
+  audio.init();
+  resetScene();
+}
+
+function updateHUD() {
+  const car = scene.car;
+  const currentSpeed = Math.abs(car.vx);
+  const currentKE = 0.5 * car.mass * currentSpeed * currentSpeed;
+
+  // Status pill
+  const pill = document.getElementById('statusPill');
+  const statusTxt = document.getElementById('statusText');
+  pill.className = 'status-pill ' + state;
+  statusTxt.textContent = state.toUpperCase();
+
+  // Speed
+  document.getElementById('hudSpeed').textContent = currentSpeed.toFixed(1);
+  document.getElementById('hudSpeedKmh').textContent = (currentSpeed * 3.6).toFixed(1) + ' km/h';
+
+  // Impact Speed
+  if (impacted) {
+    document.getElementById('hudImpactSpeed').textContent = impactSpeed.toFixed(1) + ' m/s';
+    document.getElementById('hudImpactSpeedKmh').textContent = (impactSpeed * 3.6).toFixed(1) + ' km/h';
+  } else {
+    document.getElementById('hudImpactSpeed').textContent = '–';
+    document.getElementById('hudImpactSpeedKmh').textContent = '–';
+  }
+
+  // Peak Deceleration
+  if (peakDecelG > 0) {
+    document.getElementById('hudPeakDecel').textContent = peakDecelG.toFixed(1) + ' G';
+    document.getElementById('hudPeakDecelMps').textContent = (peakDecelG * 9.81).toFixed(0) + ' m/s²';
+  } else {
+    document.getElementById('hudPeakDecel').textContent = '–';
+    document.getElementById('hudPeakDecelMps').textContent = '–';
+  }
+
+  // Moving bricks count
+  let movingCount = 0;
+  let displacedCount = 0;
+  const totalBricks = scene.world.bricks.length;
+
+  for (const b of scene.world.bricks) {
+    if (!b.asleep && (b.vx * b.vx + b.vy * b.vy > 0.04 || Math.abs(b.w) > 0.1)) movingCount++;
+    const dx = b.x - b.x0, dy = b.y - b.y0;
+    if (dx * dx + dy * dy > 0.04) displacedCount++;
+  }
+
+  document.getElementById('hudMovingBricks').textContent = movingCount;
+  document.getElementById('hudTotalBricks').textContent = totalBricks;
+  document.getElementById('hudMovingPct').textContent = Math.round((movingCount / totalBricks) * 100) + '% active';
+
+  // Displaced percentage
+  document.getElementById('hudWallDisplaced').textContent = Math.round((displacedCount / totalBricks) * 100) + '%';
+
+  // Elapsed time & Energy
+  document.getElementById('hudElapsed').textContent = simTime.toFixed(2);
+  document.getElementById('hudCarKE').textContent = (currentKE / 1000).toFixed(1) + ' kJ KE';
+
+  // Energy Progress Bar
+  const energyRatio = initialCarKE > 0 ? Math.max(0, Math.min(1, currentKE / initialCarKE)) : 1;
+  document.getElementById('energyBar').style.width = (energyRatio * 100).toFixed(1) + '%';
+}
+
+function bindControls() {
+  const btnTest = document.getElementById('btnTest');
+  const btnReset = document.getElementById('btnReset');
+  const btnSettingsToggle = document.getElementById('btnSettingsToggle');
+  const settingsPanel = document.getElementById('settingsPanel');
+  const btnDefaults = document.getElementById('btnDefaults');
+  const btnSpeedToggle = document.getElementById('btnSpeedToggle');
+  const speedLabel = document.getElementById('speedLabel');
+  const btnSoundToggle = document.getElementById('btnSoundToggle');
+
+  btnTest.addEventListener('click', launchTest);
+  btnReset.addEventListener('click', resetExperiment);
+
+  btnSettingsToggle.addEventListener('click', () => {
+    settingsPanel.classList.toggle('collapsed');
+    btnSettingsToggle.classList.toggle('active');
+    setTimeout(computeViewScale, 200);
+  });
+
+  btnDefaults.addEventListener('click', () => {
+    Object.assign(settings, DEFAULTS);
+    syncUIWithSettings();
+    resetScene();
+  });
+
+  const speeds = [1.0, 0.5, 0.25];
+  let speedIdx = 0;
+  btnSpeedToggle.addEventListener('click', () => {
+    speedIdx = (speedIdx + 1) % speeds.length;
+    timeScale = speeds[speedIdx];
+    speedLabel.textContent = timeScale.toFixed(2) + '×';
+  });
+
+  btnSoundToggle.addEventListener('click', () => {
+    audio.init();
+    audio.enabled = !audio.enabled;
+    document.getElementById('soundIconOn').style.display = audio.enabled ? 'block' : 'none';
+    document.getElementById('soundIconOff').style.display = audio.enabled ? 'none' : 'block';
+  });
+
+  // Keyboard shortcuts
+  window.addEventListener('keydown', (e) => {
+    if (e.target.tagName === 'INPUT') return;
+    if (e.code === 'Space') {
+      e.preventDefault();
+      launchTest();
+    } else if (e.code === 'KeyR') {
+      e.preventDefault();
+      resetExperiment();
+    }
+  });
+
+  // Settings Sync Helpers
+  function bindSetting(paramKey, rngId, numId, txtId, scaleFmt = 1) {
+    const rng = document.getElementById(rngId);
+    const num = document.getElementById(numId);
+    const txt = txtId ? document.getElementById(txtId) : null;
+
+    const update = (val) => {
+      let v = parseFloat(val);
+      if (isNaN(v)) return;
+      settings[paramKey] = v;
+      rng.value = v;
+      num.value = v;
+      if (txt) txt.textContent = (v).toFixed(scaleFmt);
+      if (paramKey === 'carSpeed') {
+        document.getElementById('txtCarSpeedKmh').textContent = `(${(v * 3.6).toFixed(1)} km/h)`;
+      } else if (paramKey === 'cols') {
+        document.getElementById('txtWallWidth').textContent = `(${(v * settings.brickW).toFixed(2)} m)`;
+      } else if (paramKey === 'rows') {
+        document.getElementById('txtWallHeight').textContent = `(${(v * settings.brickH).toFixed(2)} m)`;
+      }
+      if (state === 'ready') resetScene();
+    };
+
+    rng.addEventListener('input', e => update(e.target.value));
+    num.addEventListener('input', e => update(e.target.value));
+  }
+
+  bindSetting('carSpeed', 'rngCarSpeed', 'numCarSpeed', 'txtCarSpeed', 1);
+  bindSetting('cols', 'rngCols', 'numCols', 'txtCols', 0);
+  bindSetting('rows', 'rngRows', 'numRows', 'txtRows', 0);
+  bindSetting('layers', 'rngLayers', 'numLayers', 'txtLayers', 0);
+  bindSetting('brickMass', 'rngMass', 'numMass', 'txtMass', 1);
+
+  bindSetting('brickFriction', 'rngBrickMu', 'numBrickMu', 'txtBrickMu', 2);
+  bindSetting('brickRestitution', 'rngBrickE', 'numBrickE', 'txtBrickE', 2);
+  bindSetting('groundFriction', 'rngGroundMu', 'numGroundMu', 'txtGroundMu', 2);
+  bindSetting('gravity', 'rngGravity', 'numGravity', 'txtGravity', 1);
+  bindSetting('carMass', 'rngCarMass', 'numCarMass', 'txtCarMass', 0);
+
+  // Presets
+  const presets = {
+    baseline: { carSpeed: 22.0, cols: 12, rows: 8, layers: 2, brickMass: 2.5 },
+    highspeed: { carSpeed: 40.0, cols: 12, rows: 8, layers: 2, brickMass: 2.5 },
+    bunker: { carSpeed: 24.0, cols: 16, rows: 10, layers: 4, brickMass: 5.0 },
+    heavy: { carSpeed: 30.0, cols: 10, rows: 6, layers: 3, brickMass: 9.0 }
+  };
+
+  document.querySelectorAll('.preset-btn').forEach(btn => {
+    btn.addEventListener('click', () => {
+      const p = presets[btn.dataset.preset];
+      if (p) {
+        Object.assign(settings, p);
+        syncUIWithSettings();
+        resetScene();
+      }
+    });
+  });
+}
+
+function syncUIWithSettings() {
+  const sync = (idRng, idNum, idTxt, val, d = 1) => {
+    document.getElementById(idRng).value = val;
+    document.getElementById(idNum).value = val;
+    if (idTxt) document.getElementById(idTxt).textContent = Number(val).toFixed(d);
+  };
+  sync('rngCarSpeed', 'numCarSpeed', 'txtCarSpeed', settings.carSpeed, 1);
+  sync('rngCols', 'numCols', 'txtCols', settings.cols, 0);
+  sync('rngRows', 'numRows', 'txtRows', settings.rows, 0);
+  sync('rngLayers', 'numLayers', 'txtLayers', settings.layers, 0);
+  sync('rngMass', 'numMass', 'txtMass', settings.brickMass, 1);
+
+  sync('rngBrickMu', 'numBrickMu', 'txtBrickMu', settings.brickFriction, 2);
+  sync('rngBrickE', 'numBrickE', 'txtBrickE', settings.brickRestitution, 2);
+  sync('rngGroundMu', 'numGroundMu', 'txtGroundMu', settings.groundFriction, 2);
+  sync('rngGravity', 'numGravity', 'txtGravity', settings.gravity, 1);
+  sync('rngCarMass', 'numCarMass', 'txtCarMass', settings.carMass, 0);
+
+  document.getElementById('txtCarSpeedKmh').textContent = `(${(settings.carSpeed * 3.6).toFixed(1)} km/h)`;
+  document.getElementById('txtWallWidth').textContent = `(${(settings.cols * settings.brickW).toFixed(2)} m)`;
+  document.getElementById('txtWallHeight').textContent = `(${(settings.rows * settings.brickH).toFixed(2)} m)`;
+}
+
+/* =====================================================================
+   WINDOW RESIZE & INITIALIZATION
+   ===================================================================== */
+function resize() {
+  dpr = window.devicePixelRatio || 1;
+  W = window.innerWidth;
+  H = window.innerHeight;
+  canvas.width = Math.round(W * dpr);
+  canvas.height = Math.round(H * dpr);
+  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
+  if (scene) {
+    computeViewScale();
+    camera.restX = restCameraX();
+    camera.x = camera.target = camera.restX;
+    drawScene();
+  }
+}
+
+window.addEventListener('resize', resize);
+
+window.addEventListener('DOMContentLoaded', () => {
+  bindControls();
+  resize();
+  resetScene();
+  requestAnimationFrame(animate);
+});
+
+})();
+</script>
+</body>
+</html>

